+#[derive(Clone, Debug)]
+enum Op {
+    Add(i32),
+    Sub(i32),
+}
+
+struct Accumulator {
+    accumulator: Mutex<i32>,
+}
+
+impl Accumulator {
+    fn new() -> Accumulator {
+        let accumulator = Mutex::new(0);
+        Accumulator { accumulator }
+    }
+}
+
+impl StateMachine for Accumulator {
+    type Input = Op;
+    type Output = ();
+
+    fn apply(&self, op: Op) {
+        let mut accumulator = self.accumulator.lock();
+        match op {
+            Op::Add(value) => {
+                *accumulator += value;
+            }
+            Op::Sub(value) => {
+                *accumulator -= value;
+            }
+        }
+    }
+}
